     1→import { Modal, App, Notice } from 'obsidian';
     2→import * as THREE from 'three';
     3→import { GraphData, PaperNode } from '../types/Paper';
     4→import { ForceLayout } from '../physics/ForceLayout';
     5→import { ThreeRenderer } from '../rendering/ThreeRenderer';
     6→// TODO: Uncomment when UIManager is ready
     7→// import { UIManager } from '../ui/UIManager';
     8→
     9→/**
    10→ * Camera controls for the 3D graph
    11→ * Supports orbit, zoom, pan, and reset
    12→ */
    13→class GraphControls {
    14→  private position = new THREE.Vector3();
    15→  private target = new THREE.Vector3(0, 0, 0);
    16→  private distance = 400;
    17→  private theta = Math.PI * 0.5;
    18→  private phi = Math.PI * 0.5;
    19→
    20→  private isDragging = false;
    21→  private previousMousePosition = { x: 0, y: 0 };
    22→
    23→  private minDistance = 100;
    24→  private maxDistance = 1500;
    25→
    26→  constructor(
    27→    private camera: THREE.PerspectiveCamera,
    28→    private canvas: HTMLCanvasElement,
    29→    private onUpdate?: () => void
    30→  ) {
    31→    this.setupEventListeners();
    32→    this.updateCamera();
    33→  }
    34→
    35→  /**
    36→   * Setup mouse and keyboard event listeners
    37→   */
    38→  private setupEventListeners(): void {
    39→    // Mouse down
    40→    this.canvas.addEventListener('mousedown', (e) => {
    41→      if (e.button === 2) {
    42→        // Right click for orbit
    43→        this.isDragging = true;
    44→        this.previousMousePosition = { x: e.clientX, y: e.clientY };
    45→      }
    46→    });
    47→
    48→    // Mouse move
    49→    this.canvas.addEventListener('mousemove', (e) => {
    50→      if (this.isDragging) {
    51→        const deltaX = e.clientX - this.previousMousePosition.x;
    52→        const deltaY = e.clientY - this.previousMousePosition.y;
    53→
    54→        this.theta -= deltaX * 0.01;
    55→        this.phi -= deltaY * 0.01;
    56→
    57→        this.phi = Math.max(0.1, Math.min(Math.PI - 0.1, this.phi));
    58→
    59→        this.updateCamera();
    60→        this.onUpdate?.();
    61→      }
    62→    });
    63→
    64→    // Mouse up
    65→    this.canvas.addEventListener('mouseup', () => {
    66→      this.isDragging = false;
    67→    });
    68→
    69→    // Mouse leave
    70→    this.canvas.addEventListener('mouseleave', () => {
    71→      this.isDragging = false;
    72→    });
    73→
    74→    // Scroll for zoom
    75→    this.canvas.addEventListener('wheel', (e) => {
    76→      e.preventDefault();
    77→      this.distance += e.deltaY * 0.5;
    78→      this.distance = Math.max(this.minDistance, Math.min(this.maxDistance, this.distance));
    79→      this.updateCamera();
    80→      this.onUpdate?.();
    81→    });
    82→
    83→    // Keyboard controls
    84→    window.addEventListener('keydown', (e) => {
    85→      if (e.code === 'Space') {
    86→        // Space to reset view
    87→        this.reset();
    88→        this.onUpdate?.();
    89→      }
    90→    });
    91→
    92→    // Context menu prevention for right-click
    93→    this.canvas.addEventListener('contextmenu', (e) => {
    94→      e.preventDefault();
    95→    });
    96→  }
    97→
    98→  /**
    99→   * Update camera position based on spherical coordinates
   100→   */
   101→  private updateCamera(): void {
   102→    this.position.x = this.target.x + this.distance * Math.sin(this.phi) * Math.cos(this.theta);
   103→    this.position.y = this.target.y + this.distance * Math.cos(this.phi);
   104→    this.position.z = this.target.z + this.distance * Math.sin(this.phi) * Math.sin(this.theta);
   105→
   106→    this.camera.position.copy(this.position);
   107→    this.camera.lookAt(this.target);
   108→  }
   109→
   110→  /**
   111→   * Reset view to default
   112→   */
   113→  reset(): void {
   114→    this.distance = 400;
   115→    this.theta = Math.PI * 0.5;
   116→    this.phi = Math.PI * 0.5;
   117→    this.updateCamera();
   118→  }
   119→
   120→  /**
   121→   * Set camera target
   122→   */
   123→  setTarget(target: THREE.Vector3): void {
   124→    this.target.copy(target);
   125→    this.updateCamera();
   126→  }
   127→
   128→  /**
   129→   * Update method for external use
   130→   */
   131→  update(): void {
   132→    this.updateCamera();
   133→  }
   134→}
   135→
   136→/**
   137→ * Main 3D Graph visualization modal
   138→ * Renders 84 papers with force-directed layout and interactive controls
   139→ */
   140→export class Graph3D extends Modal {
   141→  private graphData: GraphData | null = null;
   142→  private renderer: ThreeRenderer | null = null;
   143→  private layout: ForceLayout | null = null;
   144→  private controls: GraphControls | null = null;
   145→
   146→  private selectedPaper: PaperNode | null = null;
   147→  private hoveredPaper: PaperNode | null = null;
   148→
   149→  private isLoading = false;
   150→  private frameCount = 0;
   151→  private fps = 0;
   152→
   153→  constructor(app: App) {
   154→    super(app);
   155→    this.modalEl.addClass('graph-3d-modal');
   156→  }
   157→
   158→  /**
   159→   * Load graph data before showing
   160→   */
   161→  async loadGraphData(graphData: GraphData): Promise<void> {
   162→    this.graphData = graphData;
   163→    console.log(`Loaded graph with ${graphData.nodes.length} nodes and ${graphData.edges.length} edges`);
   164→  }
   165→
   166→  /**
   167→   * Initialize the modal UI
   168→   */
   169→  onOpen(): void {
   170→    const { contentEl, titleEl } = this;
   171→    contentEl.empty();
   172→    titleEl.setText('3D Paper Graph Visualization');
   173→
   174→    // Create container for Three.js canvas
   175→    const container = contentEl.createEl('div', { cls: 'graph-3d-container' });
   176→    container.style.width = '100%';
   177→    container.style.height = '100%';
   178→    container.style.position = 'relative';
   179→
   180→    // Initialize renderer
   181→    const width = contentEl.clientWidth || window.innerWidth * 0.8;
   182→    const height = contentEl.clientHeight || window.innerHeight * 0.8;
   183→
   184→    this.renderer = new ThreeRenderer(container, width, height);
   185→
   186→    // Load and position nodes
   187→    if (this.graphData) {
   188→      this.initializeGraph();
   189→    }
   190→
   191→    // Add UI overlay for info
   192→    this.addUIOverlay(contentEl);
   193→
   194→    // Setup interaction
   195→    this.setupInteraction();
   196→  }
   197→
   198→  /**
   199→   * Initialize graph rendering
   200→   */
   201→  private async initializeGraph(): Promise<void> {
   202→    if (!this.graphData || !this.renderer) return;
   203→
   204→    this.isLoading = true;
   205→    new Notice('Computing layout...');
   206→
   207→    // Run force-directed layout
   208→    this.layout = new ForceLayout(this.graphData);
   209→    const positions = await this.layout.positionNodes(2000);
   210→
   211→    // Add nodes to scene
   212→    this.renderer.addNodes(this.graphData, positions);
   213→
   214→    // Add edges (top-5 per node)
   215→    this.renderer.addEdges(this.graphData.edges, positions, 5);
   216→
   217→    // Fit camera to view all nodes
   218→    this.renderer.fitCamera(positions);
   219→
   220→    // Start render loop
   221→    this.renderer.startRenderLoop(this.controls);
   222→
   223→    // Setup camera controls
   224→    this.setupControls();
   225→
   226→    this.isLoading = false;
   227→    new Notice('3D Graph Ready!');
   228→
   229→    console.log('Graph initialized and rendering');
   230→  }
   231→
   232→  /**
   233→   * Setup camera controls
   234→   */
   235→  private setupControls(): void {
   236→    if (!this.renderer) return;
   237→
   238→    const canvas = this.renderer['canvas'] || document.querySelector('canvas');
   239→    this.controls = new GraphControls(
   240→      this.renderer['camera'],
   241→      canvas as HTMLCanvasElement,
   242→      () => {
   243→        // Re-render on control changes
   244→        if (this.renderer) {
   245→          this.renderer['renderer'].render(this.renderer['scene'], this.renderer['camera']);
   246→        }
   247→      }
   248→    );
   249→  }
   250→
   251→  /**
   252→   * Setup mouse interaction (picking, highlighting)
   253→   */
   254→  private setupInteraction(): void {
   255→    if (!this.renderer) return;
   256→
   257→    const canvas = this.renderer['canvas'] || document.querySelector('canvas');
   258→
   259→    canvas?.addEventListener('click', (e) => {
   260→      const intersects = this.renderer!.getIntersectedObjects(e.clientX, e.clientY);
   261→
   262→      if (intersects.length > 0) {
   263→        const intersected = intersects[0].object as any;
   264→        const paperId = intersected.paperId;
   265→
   266→        if (paperId) {
   267→          this.selectPaper(intersected.paperNode);
   268→        }
   269→      }
   270→    });
   271→
   272→    canvas?.addEventListener('mousemove', (e) => {
   273→      const intersects = this.renderer!.getIntersectedObjects(e.clientX, e.clientY);
   274→
   275→      // Clear previous hover
   276→      if (this.hoveredPaper) {
   277→        this.renderer!.highlightNode(this.hoveredPaper.id, false);
   278→      }
   279→
   280→      if (intersects.length > 0) {
   281→        const intersected = intersects[0].object as any;
   282→        if (intersected.paperNode) {
   283→          this.hoveredPaper = intersected.paperNode;
   284→          this.renderer!.highlightNode(this.hoveredPaper.id, true);
   285→        }
   286→      }
   287→    });
   288→  }
   289→
   290→  /**
   291→   * Select a paper and display info
   292→   */
   293→  private selectPaper(paper: PaperNode): void {
   294→    if (this.selectedPaper?.id === paper.id) {
   295→      // Deselect if clicking same paper
   296→      if (this.renderer) {
   297→        this.renderer.highlightNode(paper.id, false);
   298→      }
   299→      this.selectedPaper = null;
   300→    } else {
   301→      // Clear previous selection
   302→      if (this.selectedPaper && this.renderer) {
   303→        this.renderer.highlightNode(this.selectedPaper.id, false);
   304→      }
   305→
   306→      // Select new paper
   307→      this.selectedPaper = paper;
   308→      if (this.renderer) {
   309→        this.renderer.highlightNode(paper.id, true);
   310→      }
   311→
   312→      // Show info
   313→      this.showPaperInfo(paper);
   314→    }
   315→  }
   316→
   317→  /**
   318→   * Display selected paper information
   319→   */
   320→  private showPaperInfo(paper: PaperNode): void {
   321→    const infoPanel = document.querySelector('.paper-info-panel') as HTMLElement;
   322→    if (!infoPanel) return;
   323→
   324→    let html = `
   325→      <h3>${paper.title}</h3>
   326→      <p><strong>ID:</strong> ${paper.id}</p>
   327→    `;
   328→
   329→    if (paper.authors) {
   330→      html += `<p><strong>Authors:</strong> ${paper.authors.join(', ')}</p>`;
   331→    }
   332→
   333→    if (paper.year) {
   334→      html += `<p><strong>Year:</strong> ${paper.year}</p>`;
   335→    }
   336→
   337→    html += `
   338→      <h4>Dimensions</h4>
   339→      <ul>
   340→        <li>Connectivity: ${(paper.dimensions.connectivity * 100).toFixed(1)}%</li>
   341→        <li>Conceptual Depth: ${(paper.dimensions.conceptual_depth * 100).toFixed(1)}%</li>
   342→        <li>Temporal: ${(paper.dimensions.temporal * 100).toFixed(1)}%</li>
   343→        <li>Completion: ${paper.dimensions.completion.toFixed(1)}%</li>
   344→        <li>Recency: ${(paper.dimensions.recency * 100).toFixed(1)}%</li>
   345→      </ul>
   346→    `;
   347→
   348→    infoPanel.innerHTML = html;
   349→  }
   350→
   351→  /**
   352→   * Add UI overlay for info panel and stats
   353→   */
   354→  private addUIOverlay(container: HTMLElement): void {
   355→    // Info panel
   356→    const infoPanel = container.createEl('div', { cls: 'paper-info-panel' });
   357→    infoPanel.style.position = 'absolute';
   358→    infoPanel.style.top = '10px';
   359→    infoPanel.style.right = '10px';
   360→    infoPanel.style.width = '300px';
   361→    infoPanel.style.background = 'rgba(0,0,0,0.8)';
   362→    infoPanel.style.color = '#fff';
   363→    infoPanel.style.padding = '15px';
   364→    infoPanel.style.borderRadius = '5px';
   365→    infoPanel.style.fontSize = '12px';
   366→    infoPanel.style.maxHeight = '50vh';
   367→    infoPanel.style.overflowY = 'auto';
   368→    infoPanel.style.fontFamily = 'monospace';
   369→    infoPanel.innerHTML = `
   370→      <p>Click to select a paper</p>
   371→      <p>Hover to highlight</p>
   372→      <p>Right-drag to orbit</p>
   373→      <p>Scroll to zoom</p>
   374→      <p>Space to reset</p>
   375→    `;
   376→
   377→    // FPS counter
   378→    const fpsCounter = container.createEl('div', { cls: 'fps-counter' });
   379→    fpsCounter.style.position = 'absolute';
   380→    fpsCounter.style.bottom = '10px';
   381→    fpsCounter.style.left = '10px';
   382→    fpsCounter.style.background = 'rgba(0,0,0,0.8)';
   383→    fpsCounter.style.color = '#0f0';
   384→    fpsCounter.style.padding = '10px';
   385→    fpsCounter.style.borderRadius = '5px';
   386→    fpsCounter.style.fontSize = '12px';
   387→    fpsCounter.style.fontFamily = 'monospace';
   388→    fpsCounter.innerHTML = 'FPS: 0';
   389→
   390→    // Update FPS counter
   391→    let lastTime = performance.now();
   392→    const updateFPS = () => {
   393→      const now = performance.now();
   394→      const delta = now - lastTime;
   395→      this.frameCount++;
   396→
   397→      if (delta >= 1000) {
   398→        this.fps = Math.round((this.frameCount * 1000) / delta);
   399→        fpsCounter.innerHTML = `FPS: ${this.fps}`;
   400→        this.frameCount = 0;
   401→        lastTime = now;
   402→      }
   403→
   404→      requestAnimationFrame(updateFPS);
   405→    };
   406→
   407→    updateFPS();
   408→  }
   409→
   410→  /**
   411→   * Clean up on modal close
   412→   */
   413→  onClose(): void {
   414→    if (this.renderer) {
   415→      this.renderer.dispose();
   416→      this.renderer = null;
   417→    }
   418→
   419→    if (this.layout) {
   420→      this.layout.stop();
   421→      this.layout = null;
   422→    }
   423→
   424→    console.log('Graph3D modal closed');
   425→  }
   426→}
