     4→/**
     5→ * Three.js WebGL renderer setup for 3D graph visualization
     6→ * Manages scene, camera, lights, and rendering loop
     7→ */
     8→export class ThreeRenderer {
     9→  private scene: THREE.Scene;
    10→  private camera: THREE.PerspectiveCamera;
    11→  private renderer: THREE.WebGLRenderer;
    12→  private canvas: HTMLCanvasElement;
    13→  private container: HTMLElement;
    14→
    15→  private nodeGeometry: THREE.BufferGeometry;
    16→  private nodeMaterial: THREE.MeshPhongMaterial;
    17→  private lineMaterial: THREE.LineBasicMaterial;
    18→
    19→  private nodeObjects: Map<string, THREE.Mesh> = new Map();
    20→  private edgeLines: Map<string, THREE.LineSegments> = new Map();
    21→
    22→  private raycaster: THREE.Raycaster;
    23→  private mouse: THREE.Vector2;
    24→
    25→  private animationFrameId: number | null = null;
    26→  private isDisposed = false;
    27→
    28→  constructor(container: HTMLElement, width: number, height: number) {
    29→    this.container = container;
    30→
    31→    // Scene setup
    32→    this.scene = new THREE.Scene();
    33→    this.scene.background = new THREE.Color(0x1a1a1a);
    34→    this.scene.fog = new THREE.Fog(0x1a1a1a, 2000, 3500);
    35→
    36→    // Camera setup (perspective, responsive)
    37→    this.camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 10000);
    38→    this.camera.position.set(0, 100, 200);
    39→    this.camera.lookAt(0, 0, 0);
    40→
    41→    // Renderer setup
    42→    this.renderer = new THREE.WebGLRenderer({
    43→      antialias: true,
    44→      alpha: true,
    45→      preserveDrawingBuffer: true,
    46→    });
    47→    this.renderer.setSize(width, height);
    48→    this.renderer.setPixelRatio(window.devicePixelRatio);
    49→    this.renderer.shadowMap.enabled = true;
    50→    this.renderer.shadowMap.type = THREE.PCFShadowMap;
    51→
    52→    this.canvas = this.renderer.domElement;
    53→    container.appendChild(this.canvas);
    54→
    55→    // Lighting
    56→    this.setupLights();
    57→
    58→    // Raycasting for interaction
    59→    this.raycaster = new THREE.Raycaster();
    60→    this.mouse = new THREE.Vector2();
    61→
    62→    // Create reusable materials
    63→    this.nodeGeometry = new THREE.SphereGeometry(1, 32, 32);
    64→    this.nodeMaterial = new THREE.MeshPhongMaterial({
    65→      emissive: 0x111111,
    66→      shininess: 100,
    67→    });
    68→    this.lineMaterial = new THREE.LineBasicMaterial({
    69→      color: 0x888888,
    70→      linewidth: 1,
    71→      fog: true,
    72→    });
    73→
    74→    // Handle window resize
    75→    window.addEventListener('resize', () => this.onWindowResize());
    76→
    77→    console.log('ThreeRenderer initialized');
    78→  }
    79→
    80→  /**
    81→   * Setup directional and ambient lighting for depth perception
    82→   */
    83→  private setupLights(): void {
    84→    // Directional light (sun)
    85→    const directional = new THREE.DirectionalLight(0xffffff, 0.8);
    86→    directional.position.set(500, 500, 300);
    87→    directional.castShadow = true;
    88→    directional.shadow.mapSize.width = 2048;
    89→    directional.shadow.mapSize.height = 2048;
    90→    directional.shadow.camera.left = -1000;
    91→    directional.shadow.camera.right = 1000;
    92→    directional.shadow.camera.top = 1000;
    93→    directional.shadow.camera.bottom = -1000;
    94→    this.scene.add(directional);
    95→
    96→    // Ambient light
    97→    const ambient = new THREE.AmbientLight(0xffffff, 0.5);
    98→    this.scene.add(ambient);
    99→
   100→    // Hemisphere light for additional depth
   101→    const hemisphere = new THREE.HemisphereLight(0x8899ff, 0xff8844, 0.3);
   102→    this.scene.add(hemisphere);
   103→  }
   104→
   105→  /**
   106→   * Add paper nodes to the scene
   107→   */
   108→  addNodes(graphData: GraphData, positions: Map<string, THREE.Vector3>, colorPalette?: string[]): void {
   109→    const palette = colorPalette || this.generateColorPalette(10);
   110→
   111→    for (const node of graphData.nodes) {
   112→      const position = positions.get(node.id);
   113→      if (!position) continue;
   114→
   115→      // Calculate size based on completion (0.5x - 2.0x)
   116→      const size = 0.5 + (node.dimensions.completion / 100) * 1.5;
   117→
   118→      // Calculate opacity based on recency (30%-100%)
   119→      const opacity = 0.3 + node.dimensions.recency * 0.7;
   120→
   121→      // Get color from domain clustering (hue)
   122→      const hueIndex = (node.dimensions.cross_domain - 1) % palette.length;
   123→      const color = new THREE.Color(palette[hueIndex]);
   124→
   125→      // Create mesh
   126→      const mesh = new THREE.Mesh(this.nodeGeometry, this.nodeMaterial.clone());
   127→      mesh.scale.set(size, size, size);
   128→      mesh.position.copy(position);
   129→      mesh.castShadow = true;
   130→      mesh.receiveShadow = true;
   131→
   132→      // Apply color and opacity
   133→      (mesh.material as THREE.MeshPhongMaterial).color = color;
   134→      (mesh.material as THREE.MeshPhongMaterial).transparent = true;
   135→      (mesh.material as THREE.MeshPhongMaterial).opacity = opacity;
   136→
   137→      // Store metadata for picking
   138→      (mesh as any).paperId = node.id;
   139→      (mesh as any).paperNode = node;
   140→
   141→      this.scene.add(mesh);
   142→      this.nodeObjects.set(node.id, mesh);
   143→    }
   144→
   145→    console.log(`Added ${graphData.nodes.length} nodes`);
   146→  }
   147→
   148→  /**
   149→   * Add edges (semantic connections) to the scene
   150→   */
   151→  addEdges(
   152→    edges: GraphEdge[],
   153→    positions: Map<string, THREE.Vector3>,
   154→    maxEdgesPerNode = 5,
   155→    colorPalette?: string[]
   156→  ): void {
   157→    const palette = colorPalette || this.generateColorPalette(10);
   158→    const nodeEdgeCount = new Map<string, number>();
   159→
   160→    // Limit edges per node for clarity
   161→    for (const edge of edges) {
   162→      const sourceCount = nodeEdgeCount.get(edge.source) || 0;
   163→      const targetCount = nodeEdgeCount.get(edge.target) || 0;
   164→
   165→      if (sourceCount >= maxEdgesPerNode || targetCount >= maxEdgesPerNode) {
   166→        continue; // Skip this edge to maintain limit
   167→      }
   168→
   169→      const sourcePos = positions.get(edge.source);
   170→      const targetPos = positions.get(edge.target);
   171→
   172→      if (!sourcePos || !targetPos) continue;
   173→
   174→      // Create line geometry
   175→      const geometry = new THREE.BufferGeometry();
   176→      geometry.setAttribute('position', new THREE.BufferAttribute(
   177→        new Float32Array([sourcePos.x, sourcePos.y, sourcePos.z, targetPos.x, targetPos.y, targetPos.z]),
   178→        3
   179→      ));
   180→
   181→      // Width proportional to similarity
   182→      const width = Math.max(1, edge.similarity * 3);
   183→
   184→      // Color as average hue of endpoints
   185→      const material = new THREE.LineBasicMaterial({
   186→        color: 0x666666,
   187→        linewidth: width,
   188→        fog: true,
   189→      });
   190→
   191→      const line = new THREE.LineSegments(geometry, material);
   192→      this.scene.add(line);
   193→
   194→      // Track edge
   195→      const edgeKey = `${edge.source}-${edge.target}`;
   196→      this.edgeLines.set(edgeKey, line);
   197→
   198→      // Increment counters
   199→      nodeEdgeCount.set(edge.source, sourceCount + 1);
   200→      nodeEdgeCount.set(edge.target, targetCount + 1);
   201→    }
   202→
   203→    console.log(`Added ${this.edgeLines.size} edges`);
   204→  }
   205→
   206→  /**
   207→   * Auto-fit camera to show all nodes
   208→   */
   209→  fitCamera(positions: Map<string, THREE.Vector3>): void {
   210→    if (positions.size === 0) return;
   211→
   212→    const box = new THREE.Box3();
   213→    for (const [, pos] of positions) {
   214→      box.expandByPoint(pos);
   215→    }
   216→
   217→    const size = box.getSize(new THREE.Vector3());
   218→    const maxDim = Math.max(size.x, size.y, size.z);
   219→    const fov = this.camera.fov * (Math.PI / 180); // Convert to radians
   220→    let cameraZ = Math.abs(maxDim / 2 / Math.tan(fov / 2));
   221→
   222→    cameraZ *= 1.5; // Add padding
   223→
   224→    const center = box.getCenter(new THREE.Vector3());
   225→    this.camera.position.set(center.x, center.y + maxDim * 0.3, center.z + cameraZ);
   226→    this.camera.lookAt(center);
   227→    this.camera.updateProjectionMatrix();
   228→  }
   229→
   230→  /**
   231→   * Start the render loop
   232→   */
   233→  startRenderLoop(controls: any): void {
   234→    const animate = () => {
   235→      this.animationFrameId = requestAnimationFrame(animate);
   236→
   237→      if (controls) {
   238→        controls.update();
   239→      }
   240→
   241→      this.renderer.render(this.scene, this.camera);
   242→    };
   243→
   244→    animate();
   245→  }
   246→
   247→  /**
   248→   * Stop the render loop
   249→   */
   250→  stopRenderLoop(): void {
   251→    if (this.animationFrameId !== null) {
   252→      cancelAnimationFrame(this.animationFrameId);
   253→      this.animationFrameId = null;
   254→    }
   255→  }
   256→
   257→  /**
   258→   * Get raycaster for picking
   259→   */
   260→  getRaycaster(): THREE.Raycaster {
   261→    return this.raycaster;
   262→  }
   263→
   264→  /**
   265→   * Get intersected objects at mouse position
   266→   */
   267→  getIntersectedObjects(clientX: number, clientY: number): THREE.Intersection[] {
   268→    const rect = this.canvas.getBoundingClientRect();
   269→    this.mouse.x = ((clientX - rect.left) / rect.width) * 2 - 1;
   270→    this.mouse.y = -((clientY - rect.top) / rect.height) * 2 + 1;
   271→
   272→    this.raycaster.setFromCamera(this.mouse, this.camera);
   273→    return this.raycaster.intersectObjects(Array.from(this.nodeObjects.values()), false);
   274→  }
   275→
   276→  /**
   277→   * Highlight a node with glow effect
   278→   */
   279→  highlightNode(paperId: string, enabled: boolean = true): void {
   280→    const mesh = this.nodeObjects.get(paperId);
   281→    if (!mesh) return;
   282→
   283→    if (enabled) {
   284→      const material = mesh.material as THREE.MeshPhongMaterial;
   285→      material.emissive.setHex(0x4488ff);
   286→      material.emissiveIntensity = 0.8;
   287→    } else {
   288→      const material = mesh.material as THREE.MeshPhongMaterial;
   289→      material.emissive.setHex(0x111111);
   290→      material.emissiveIntensity = 0;
   291→    }
   292→  }
   293→
   294→  /**
   295→   * Get a paper node by ID
   296→   */
   297→  getNodeObject(paperId: string): THREE.Mesh | undefined {
   298→    return this.nodeObjects.get(paperId);
   299→  }
   300→
   301→  /**
   302→   * Handle window resize
   303→   */
   304→  private onWindowResize(): void {
   305→    const width = this.container.clientWidth;
   306→    const height = this.container.clientHeight;
   307→
   308→    this.camera.aspect = width / height;
   309→    this.camera.updateProjectionMatrix();
   310→    this.renderer.setSize(width, height);
   311→  }
   312→
   313→  /**
   314→   * Generate a color palette for domain clustering
   315→   */
   316→  private generateColorPalette(count: number): string[] {
   317→    const palette: string[] = [];
   318→    for (let i = 0; i < count; i++) {
   319→      const hue = (i / count) * 360;
   320→      palette.push(`hsl(${hue}, 100%, 50%)`);
   321→    }
   322→    return palette;
   323→  }
   324→
   325→  /**
   326→   * Dispose of resources
   327→   */
   328→  dispose(): void {
   329→    if (this.isDisposed) return;
   330→
   331→    this.stopRenderLoop();
   332→    this.nodeGeometry.dispose();
   333→    this.nodeMaterial.dispose();
   334→    this.lineMaterial.dispose();
   335→
   336→    for (const mesh of this.nodeObjects.values()) {
   337→      (mesh.material as THREE.Material).dispose();
   338→      mesh.geometry.dispose();
   339→    }
   340→
   341→    for (const line of this.edgeLines.values()) {
   342→      (line.material as THREE.Material).dispose();
   343→      line.geometry.dispose();
   344→    }
   345→
   346→    this.renderer.dispose();
   347→    this.canvas.remove();
   348→    this.isDisposed = true;
   349→
   350→    console.log('ThreeRenderer disposed');
   351→  }
   352→}
