    19→export class CascadeGraph extends Modal {
    20→  private sourceDecisionId: string;
    21→  private cascades: DecisionCascade[];
    22→  private title: string;
    23→
    24→  constructor(app: App, sourceDecisionId: string, cascades: DecisionCascade[], title: string = 'Decision Cascades') {
