    48→      <p><strong>Impacted Decisions:</strong> ${this.cascades.length}</p>
    49→    `;
    50→
    51→    // Count by impact level
    52→    const criticalCount = this.cascades.filter(c => c.impact_level === 'critical').length;
    53→    const significantCount = this.cascades.filter(c => c.impact_level === 'significant').length;
