    96→
    97→    // Header row
    98→    const headerRow = table.createEl('tr');
    99→    headerRow.style.backgroundColor = '#f0f0f0';
   100→    ['Target Decision', 'Dependency Type', 'Impact Level', 'Description'].forEach(header => {
   101→      const th = headerRow.createEl('th');
