   154→
   155→  /**
   156→   * Render force-directed graph visualization
   157→   */
   158→  private renderCascadeGraph(container: HTMLElement): void {
   159→    // Build node and edge lists for layout
   160→    const nodeMap = new Map<string, { id: string; label: string; impact?: string }>();
   161→    const edges: Array<{ source: string; target: string; type: string }> = [];
   162→
   163→    // Add source node
   164→    nodeMap.set(this.sourceDecisionId, {
   165→      id: this.sourceDecisionId,
   166→      label: this.sourceDecisionId.slice(0, 20),
   167→      impact: 'source',
   168→    });
   169→
   170→    // Add cascade nodes and edges
   171→    for (const cascade of this.cascades) {
   172→      if (!nodeMap.has(cascade.target_decision_id)) {
   173→        nodeMap.set(cascade.target_decision_id, {
   174→          id: cascade.target_decision_id,
   175→          label: cascade.target_decision_id.slice(0, 20),
   176→          impact: cascade.impact_level,
   177→        });
   178→      }
   179→
   180→      edges.push({
   181→        source: this.sourceDecisionId,
   182→        target: cascade.target_decision_id,
   183→        type: cascade.dependency_type,
   184→      });
   185→    }
   186→
   187→    const nodes = Array.from(nodeMap.values());
   188→
   189→    // Simple force-directed layout (spring algorithm)
   190→    const positions = this.computeLayout(nodes, edges);
   191→
   192→    // Render SVG
   193→    const canvasWidth = 800;
   194→    const canvasHeight = 600;
   195→
   196→    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
   197→    svg.setAttribute('width', String(canvasWidth));
   198→    svg.setAttribute('height', String(canvasHeight));
   199→    svg.setAttribute('viewBox', `0 0 ${canvasWidth} ${canvasHeight}`);
   200→    svg.style.border = '1px solid #ddd';
   201→
   202→    // Draw edges first (so they appear behind nodes)
   203→    for (const edge of edges) {
   204→      const sourcePos = positions.get(edge.source)!;
   205→      const targetPos = positions.get(edge.target)!;
   206→
   207→      // Edge line
   208→      const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
   209→      line.setAttribute('x1', String(sourcePos.x));
   210→      line.setAttribute('y1', String(sourcePos.y));
   211→      line.setAttribute('x2', String(targetPos.x));
   212→      line.setAttribute('y2', String(targetPos.y));
   213→      line.setAttribute('stroke', '#999');
   214→      line.setAttribute('stroke-width', '2');
   215→      svg.appendChild(line);
   216→
   217→      // Arrow head
   218→      const angle = Math.atan2(targetPos.y - sourcePos.y, targetPos.x - sourcePos.x);
   219→      const arrowSize = 10;
   220→      const arrowX = targetPos.x - arrowSize * Math.cos(angle);
   221→      const arrowY = targetPos.y - arrowSize * Math.sin(angle);
   222→
   223→      const arrow = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
   224→      const p1x = arrowX;
   225→      const p1y = arrowY;
   226→      const p2x = arrowX - arrowSize * Math.cos(angle - Math.PI / 6);
   227→      const p2y = arrowY - arrowSize * Math.sin(angle - Math.PI / 6);
   228→      const p3x = arrowX - arrowSize * Math.cos(angle + Math.PI / 6);
   229→      const p3y = arrowY - arrowSize * Math.sin(angle + Math.PI / 6);
   230→
   231→      arrow.setAttribute('points', `${p1x},${p1y} ${p2x},${p2y} ${p3x},${p3y}`);
   232→      arrow.setAttribute('fill', '#999');
   233→      svg.appendChild(arrow);
   234→    }
   235→
   236→    // Draw nodes
   237→    for (const node of nodes) {
   238→      const pos = positions.get(node.id)!;
   239→      const color = this.getColorForImpact(node.impact || 'minor');
   240→      const radius = node.impact === 'source' ? 15 : 12;
   241→
   242→      // Circle
   243→      const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
   244→      circle.setAttribute('cx', String(pos.x));
   245→      circle.setAttribute('cy', String(pos.y));
   246→      circle.setAttribute('r', String(radius));
   247→      circle.setAttribute('fill', color);
   248→      circle.setAttribute('stroke', '#333');
   249→      circle.setAttribute('stroke-width', '1.5');
   250→      circle.style.cursor = 'pointer';
   251→      svg.appendChild(circle);
   252→
   253→      // Label
   254→      const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
   255→      text.setAttribute('x', String(pos.x));
   256→      text.setAttribute('y', String(pos.y + 4));
   257→      text.setAttribute('text-anchor', 'middle');
   258→      text.setAttribute('font-size', '10');
   259→      text.setAttribute('fill', '#fff');
   260→      text.setAttribute('font-weight', 'bold');
   261→      text.textContent = node.label;
   262→      svg.appendChild(text);
   263→    }
   264→
   265→    container.appendChild(svg);
   266→  }
   267→
   268→  /**
   269→   * Compute node positions using spring force algorithm
   270→   */
   271→  private computeLayout(
   272→    nodes: any[],
   273→    edges: Array<{ source: string; target: string; type: string }>
   274→  ): Map<string, { x: number; y: number }> {
   275→    const positions = new Map<string, { x: number; y: number }>();
   276→    const width = 800;
   277→    const height = 600;
   278→
   279→    // Initialize random positions
   280→    for (const node of nodes) {
   281→      positions.set(node.id, {
   282→        x: Math.random() * width,
   283→        y: Math.random() * height,
   284→      });
   285→    }
   286→
   287→    // Spring layout simulation (simplified)
   288→    const iterations = 50;
   289→    const k = 50; // Spring constant
   290→    const c = 0.1; // Damping
   291→
   292→    for (let iter = 0; iter < iterations; iter++) {
   293→      const forces = new Map<string, { fx: number; fy: number }>();
   294→
   295→      // Initialize forces
   296→      for (const node of nodes) {
   297→        forces.set(node.id, { fx: 0, fy: 0 });
   298→      }
   299→
   300→      // Repulsive forces (nodes push each other away)
   301→      for (let i = 0; i < nodes.length; i++) {
   302→        for (let j = i + 1; j < nodes.length; j++) {
   303→          const n1 = nodes[i];
   304→          const n2 = nodes[j];
   305→          const p1 = positions.get(n1.id)!;
   306→          const p2 = positions.get(n2.id)!;
   307→
   308→          const dx = p2.x - p1.x;
   309→          const dy = p2.y - p1.y;
   310→          const dist = Math.sqrt(dx * dx + dy * dy) || 1;
   311→
   312→          const force = -k / (dist * dist);
   313→          const fx = (force * dx) / dist;
   314→          const fy = (force * dy) / dist;
   315→
   316→          const f1 = forces.get(n1.id)!;
   317→          f1.fx += fx;
   318→          f1.fy += fy;
   319→
   320→          const f2 = forces.get(n2.id)!;
   321→          f2.fx -= fx;
   322→          f2.fy -= fy;
   323→        }
   324→      }
   325→
   326→      // Attractive forces (connected nodes pull each other)
   327→      for (const edge of edges) {
   328→        const p1 = positions.get(edge.source)!;
   329→        const p2 = positions.get(edge.target)!;
   330→
   331→        const dx = p2.x - p1.x;
   332→        const dy = p2.y - p1.y;
   333→        const dist = Math.sqrt(dx * dx + dy * dy) || 1;
   334→
   335→        const force = (dist * dist) / (k * 10);
   336→        const fx = (force * dx) / dist;
   337→        const fy = (force * dy) / dist;
   338→
   339→        const f2 = forces.get(edge.target)!;
   340→        f2.fx -= fx;
   341→        f2.fy -= fy;
   342→
   343→        const f1 = forces.get(edge.source)!;
   344→        f1.fx += fx;
   345→        f1.fy += fy;
   346→      }
   347→
   348→      // Update positions
   349→      for (const node of nodes) {
   350→        const force = forces.get(node.id)!;
   351→        const pos = positions.get(node.id)!;
   352→
   353→        pos.x += force.fx * c;
   354→        pos.y += force.fy * c;
   355→
   356→        // Keep within bounds
   357→        pos.x = Math.max(20, Math.min(780, pos.x));
   358→        pos.y = Math.max(20, Math.min(580, pos.y));
   359→      }
   360→    }
   361→
   362→    return positions;
   363→  }
   364→
   365→  /**
   366→   * Get color for impact level
   367→   */
   368→  private getColorForImpact(impact: string): string {
   369→    const colors: Record<string, string> = {
   370→      critical: '#ef4444', // red
   371→      significant: '#f97316', // orange
   372→      minor: '#9ca3af', // gray
   373→      source: '#3b82f6', // blue
   374→    };
   375→    return colors[impact] || '#9ca3af';
   376→  }
   377→
   378→  onClose(): void {
   379→    const { contentEl } = this;
   380→    contentEl.empty();
   381→  }
   382→}
